package net.minecraft.client.gui; import java.awt.*; import java.awt.image.BufferedImage;
public class Font { public static final java.awt.Font F=new java.awt.Font("DejaVu Sans Mono", java.awt.Font.BOLD, 9); static final FontMetrics M=new BufferedImage(1,1,1).getGraphics().getFontMetrics(F);
 public int width(String s){return M.stringWidth(s)*8/9;} public int width(net.minecraft.network.chat.Component c){return width(c.getString());} public String plainSubstrByWidth(String s,int w){ while(s.length()>1&&width(s)>w) s=s.substring(0,s.length()-1); return s; }  public java.util.List<net.minecraft.util.FormattedCharSequence> split(net.minecraft.network.chat.Component c,int w){ java.util.List<net.minecraft.util.FormattedCharSequence> out=new java.util.ArrayList<>(); StringBuilder line=new StringBuilder(); for(String word:c.getString().split(" ")){ String t=line.length()==0?word:line+" "+word; if(width(t)>w&&line.length()>0){ out.add(new net.minecraft.util.FormattedCharSequence(line.toString())); line=new StringBuilder(word);} else line=new StringBuilder(t);} if(line.length()>0) out.add(new net.minecraft.util.FormattedCharSequence(line.toString())); return out; } }